auth.probe_js:
// DELIBERATE OMISSION — READ THIS BEFORE "IMPROVING" THIS PROBE.
// (1) The web client keeps an account credential in browser storage. This probe does not read it,
//     does not test for it, does not name it and never logs it. Lifting that value out of the page
//     turns a human session into a self-bot, which is exactly what Discord's ToS forbids and what
//     gets accounts terminated. The evidence below needs no credential at all.
// (2) Discord's REST API authenticates on an Authorization header, NOT on cookies. A credentialed
//     same-origin fetch of /api/v9/users/@me therefore answers 401 on a perfectly live session.
//     Do not "fix" this probe by adding that fetch — it is a false negative by construction.
let why;
try {
  if (/^\/(login|register)/.test(location.pathname)) {
    const f = document.querySelector('input[name="email"], form[class*="authBox"], [class*="authBox"]');
    if (f) return {signed_in: false, why: 'login form rendered'};
  }
} catch (e) { /* location is always readable here, but never let it be fatal */ }
// The user area at the bottom of the sidebar mounts only for an authenticated client.
const panel = document.querySelector('[aria-label="User area"], section[class*="panels"], [class*="panels-"] [class*="avatarWrapper"]');
if (panel) {
  let as;
  try {
    const tag = document.querySelector('[class*="nameTag"] [class*="title"], [class*="nameTag"], [class*="panels"] [class*="username"]');
    if (tag && tag.textContent) as = tag.textContent.trim().split('\n')[0].slice(0, 64) || undefined;
  } catch (e) { /* identity is a nicety; the verdict does not depend on it */ }
  return {signed_in: true, as: as, why: 'user area panel is mounted'};
}
const rail = document.querySelector('[aria-label="Servers"], nav[class*="guilds"]');
if (rail) return {signed_in: true, why: 'server rail is mounted'};
return {signed_in: false, why: why || 'no user area and no server rail — client is not authenticated, or the SPA has not finished booting (give it a few seconds and re-probe)'};
